    /**
     * 工作流诊断incident
     *
     * @param incident 事件
     * @param taskId 任务id
     * @return 诊断报告
     */
    public IncidentReport incidentDiagnosisWorkflow(Incident incident, Long taskId) {
        Long incidentCsn = incident.getCsn();
        IncidentReport incidentReport = new IncidentReport();
        LOGGER.info("start to get incident workflow diagnosis report with incidentCsn {}", incidentCsn);

        try {
            IncidentRootAnalysisDetailDto incidentRootAnalysisDetailDto = incidentRootAnalysis(incident);
            IncidentRootAnalysisResult incidentRootAnalysisResult =
                incidentRootAnalysisDetailDto.getRootAnalysisResult();
            boolean analysisSuccess = incidentRootAnalysisDetailDto.isAnalysisSuccess();
            if (analysisSuccess) {
                incidentReport.setAnalysisSuccess(true);
                sendLlmAnalysisResult(taskId, null, incidentCsn, IncidentConstant.INCIDENT_ANALYSIS_SUCCESS_STATUS);
            } else {
                sendLlmAnalysisResult(taskId, null, incidentCsn, IncidentConstant.INCIDENT_ANALYSIS_FAILED_STATUS);
            }
            if (incidentRootAnalysisResult != null && analysisSuccess) {
                String incidentName = incidentRootAnalysisResult.getIncidentName();
                String rootEventId = incidentRootAnalysisResult.getRootEventId();
                String report = incidentDiagnoseLlmEngine(incident, incidentRootAnalysisResult);
                String mopText = mopGenerate(incidentRootAnalysisResult, incident);
                incidentReport.setReport(report);
                incidentReport.setIncidentName(incidentName);
                incidentReport.setRootEventId(rootEventId);
                incidentReport.setHandlingSuggestion(mopText);
                LOGGER.info("[incidentDiagnosisWorkflow] csn={}, root id={}, incident name ={}",
                    incidentCsn,
                    rootEventId,
                    incidentName);
            } else {
                LOGGER.error("[incidentDiagnosisWorkflow] incidentRootAnalysisResult is null");
            }
        } catch (ServiceException e) {
            LOGGER.error("Error occurred during incident diagnosis workflow for incidentCsn={}, msg={}",
                incidentCsn, e.getMessage());
        }
        LOGGER.info("get incident workflow diagnosis report complete with incidentCsn {}", incidentCsn);
        return incidentReport;
    }

