    /**
     * 将KeyEvent列表转换为Event列表
     *
     * @param keyEvents KeyEvent列表
     * @return 转换后的Event列表
     */
    public List<Event> convertKeyEventsToEvents(List<KeyEvent> keyEvents) {
        if (keyEvents == null || keyEvents.isEmpty()) {
            return new ArrayList<>();
        }

        return keyEvents.stream()
            .map(this::convertKeyEventToEvent)
            .collect(Collectors.toList());
    }

