    /**
     * 检查是否具有该拓扑解决方案的权限
     *
     * @param context context
     * @param solutionName 解决方案名称
     * @return boolean
     * @throws ServiceException 异常时抛出
     */
    public boolean checkTopoSolutionAuth(HttpContext context, String solutionName) throws ServiceException {
        LOGGER.info("[checkTopoSolutionAuth] start, solutionName: {}", solutionName);
        String countIncidentUrl = TOPO_AUTH_SOLUTION_URL + "?timestamp=0";
        RestfulResponse response = RestUtil.sendRestRequest(
            context.getHttpServletRequest(),
            RestConstant.RESTFUL_METHOD_GET,
            countIncidentUrl,
            null,
            getDefaultRestOptions()
        );
        if (response == null || response.getStatus() != RestConstant.STATUS_OK) {
            throw new ServiceException("Failed to get topo auth solution, status: " + (response != null ? response.getStatus() : "null"));
        }
        List<TopoSolutionDto> solutionList = JSON.parseArray(response.getResponseContent(), TopoSolutionDto.class);
        return solutionList.stream().map(TopoSolutionDto::getRealSolutionName).toList().contains(solutionName);
    }

    public AIDiagnosisSummary getCountIncident(HttpContext context, String solutionName)
        throws ServiceException {
        try {
            LOGGER.info("getCountIncident start, solutionName: {}", solutionName);
            if (!ContextUtils.getContext().getAdmin() && !checkTopoSolutionAuth(context, solutionName)) {
                LOGGER.error("[getCountIncident] no topo solution auth: {}", solutionName);
                return new AIDiagnosisSummary(0, 0, 0, 0, 0, 0, 0);
            }
            String countIncidentUrl = COUNT_INCIDENT_URL + "?solutionName=" + solutionName;

            RestfulResponse response = RestUtil.sendRestRequest(
                context.getHttpServletRequest(),
                RestConstant.RESTFUL_METHOD_GET,
                countIncidentUrl,
                null,
                getDefaultRestOptions()
            );

            if (response == null || response.getStatus() != 200) {
                throw new ServiceException("Failed to get count incident, status: " +
                    (response != null ? response.getStatus() : "null"));
            }

            ResponseResult responseResult = JSON.parseObject(response.getResponseContent(), ResponseResult.class);

            if (responseResult.getResultCode() == null || responseResult.getResultCode() != 0) {
                throw new ServiceException("API returned error: " + responseResult.getResultMessage());
            }

            LOGGER.info("getCountIncident data {}", responseResult.getData());
            String dataJson = JSON.toJSONString(responseResult.getData());
            AIDiagnosisSummary summary = JSON.parseObject(dataJson, AIDiagnosisSummary.class);

            LOGGER.info("getCountIncident success, summary: {}", summary);
            return summary;

        } catch (Exception e) {
            throw new ServiceException("Error while calling countincident API", e);
        }
    }

