    public AiIncidentListQueryParam queryParam2AiIncidentQuery(IncidentQueryParam param) {
        AiIncidentListQueryParam queryParam = new AiIncidentListQueryParam();
        queryParam.setSolutionName(param.getSolutionName());
        queryParam.setPaging(param.getPaging());
        queryParam.setPriorities(param.getPriorities());
        queryParam.setCsn(param.getCsn());
        queryParam.setName(param.getName());
        queryParam.setStatusList(param.getStatusList());
        queryParam.setStartTime(param.getStartCreateTime());
        queryParam.setEndTime(param.getEndCreateTime());
        queryParam.setMarkStatus(param.getMarkStatus());
        queryParam.setIncidentType(param.getIncidentType());
        return queryParam;
    }

    public AiIncidentListQueryParam convertQueryParam(IncidentQueryParam param) {
        LOGGER.info("IncidentQueryParam is {}", param);
        AiIncidentListQueryParam queryParam = queryParam2AiIncidentQuery(param);

        List<Integer> diagnosticStatus = new ArrayList<>(convertPendingStatus(param));
        if (CollectionUtils.isNotEmpty(param.getDiagnosticStatus())) {
            List<Integer> statusList = param.getDiagnosticStatus().stream()
                .map(DiagnosticStatusEnum::fromName)
                .map(DiagnosticStatusEnum::toIncidentConstantCode)
                .toList();
            diagnosticStatus.addAll(statusList);
        }
        queryParam.setDiagnosticStatus(diagnosticStatus);

        List<Integer> diagnosisType = new ArrayList<>();
        if (StringUtils.isNotEmpty(param.getDiagnosticType())) {
            diagnosisType.add(DiagnosticTypeEnum.fromName(param.getDiagnosticType()).toIncidentConstantCode());
        }
        queryParam.setDiagnosisType(diagnosisType);

        LOGGER.info("IncidentQueryParam convert param {}", queryParam);
        return queryParam;
    }

    public static List<Integer> convertPendingStatus(IncidentQueryParam param) {
        List<String> status = param.getDiagnosticStatus();
        List<Integer> res = new ArrayList<>();
        if (CollectionUtils.isEmpty(status)) {
            return res;
        }

        if (!status.contains(DiagnosticStatusEnum.PENDING_DIAGNOSIS.name())) {
            return res;
        }

        res.addAll(Arrays.asList(DIAGNOSIS_STATUS_NOT, DIAGNOSIS_STATUS_ABLE, DIAGNOSIS_STATUS_NO_RESOURCE));
        param.getDiagnosticStatus().remove(DiagnosticStatusEnum.PENDING_DIAGNOSIS.name());
        return res;
    }

