    public List<Incident> getTopNAIIncidents(HttpContext context, String solutionName, Integer num, Integer[] status)
        throws ServiceException {
        try {
            LOGGER.info("getTopNAIIncidents start, solutionName: {}, num: {}", solutionName, num);
            if (!ContextUtils.getContext().getAdmin() && !checkTopoSolutionAuth(context, solutionName)) {
                LOGGER.error("[getTopNAIIncidents] no topo solution auth: {}", solutionName);
                return new ArrayList<>();
            }

            Comparator<Incident> comparator = (i1, i2) -> {
                int priorityCompare = comparePriority(i1.getPriority(), i2.getPriority());
                if (priorityCompare != 0) {
                    return priorityCompare;
                }
                return Long.compare(i1.getOccurTime(), i2.getOccurTime());
            };

            PriorityQueue<Incident> minHeap = new PriorityQueue<>(num, comparator);

            IncidentQueryParam queryParam = new IncidentQueryParam();
            queryParam.setSolutionName(solutionName);
            queryParam.setStatusList(convertStatusToStringList(status));

            Paging paging = new Paging();
            paging.setPageSize(100);
            queryParam.setPaging(paging);

            int pageNum = 1;
            while (true) {
                paging.setPageNumber(pageNum);
                EntityList<JSONObject> entityList = aiIncidentList(context, queryParam);
                if (entityList == null || entityList.getObjects() == null || entityList.getObjects().isEmpty()) {
                    break;
                }

                List<JSONObject> currentBatch = entityList.getObjects();
                rerank(num, currentBatch, minHeap, comparator);
                if (currentBatch.size() < paging.getPageSize()) {
                    break;
                }
                pageNum++;
            }
            List<Incident> result = new ArrayList<>(minHeap);
            result.sort((i1, i2) -> {
                int p = comparePriority(i2.getPriority(), i1.getPriority());
                if (p != 0) {
                    return p;
                }
                return Long.compare(i2.getOccurTime(), i1.getOccurTime());
            });
            LOGGER.info("getTopNAIIncidents success, returning {} incidents", result.size());
            return result;
        } catch (Exception e) {
            LOGGER.error("Error while getting top N AI incidents", e);
            throw new ServiceException("Error while getting top N AI incidents", e);
        }
    }

    private void rerank(Integer num, List<JSONObject> currentBatch, PriorityQueue<Incident> minHeap,
        Comparator<Incident> comparator) {
        for (JSONObject json : currentBatch) {
            Incident incident = json.toJavaObject(Incident.class);
            incident.setCategory("INCIDENT");
            if (minHeap.size() < num) {
                minHeap.offer(incident);
            } else {
                if (comparator.compare(incident, minHeap.peek()) > 0) {
                    minHeap.poll();
                    minHeap.offer(incident);
                }
            }
        }
    }

    private List<String> convertStatusToStringList(Integer[] statusArray) {
        if (statusArray == null) {
            return new ArrayList<>();
        }

        return Arrays.stream(statusArray)
            .filter(Objects::nonNull)
            .map(IncidentStatus::of)
            .filter(Objects::nonNull)
            .map(IncidentStatus::name)
            .collect(Collectors.toList());
    }

    private int comparePriority(IncidentPriority priority1,
        IncidentPriority priority2) {
        int p1 = getPriorityValue(priority1);
        int p2 = getPriorityValue(priority2);
        return Integer.compare(p1, p2);
    }

    private int getPriorityValue(IncidentPriority priority) {
        if (priority == null) {
            return 5; // Unknown priority goes last
        }
        switch (priority) {
            case CRITICAL:
                return 1;
            case HIGH:
                return 2;
            case MEDIUM:
                return 3;
            case LOW:
                return 4;
            default:
                return 5;
        }
    }

    /**
     * 查询大模型智能事件诊断状态
     *
     * @param context HttpContext
     * @param param IncidentDiagnosisStatusParam
     * @return AIIncidentDiagnosisStatusDto
     * @throws ServiceException 异常时抛出
     */
    public AIIncidentDiagnosisStatusDto getIncidentDiagnosisStatus(HttpContext context,
        IncidentDiagnosisStatusParam param)
        throws ServiceException {
        try {
            String solutionName = param.getSolutionName();
            Long incidentCsn = param.getIncidentCsn();
            LOGGER.info("[getIncidentDiagnosisStatus] get incident diagnosis status solution={}, csn={}",
                solutionName,
                incidentCsn);
            String jsonData = JSON.toJSONString(param);
            RestfulParametes restfulParametes = new RestfulParametes();
            restfulParametes.setRawData(jsonData);
            RestfulResponse response = RestUtil.sendRestRequest(context.getHttpServletRequest(),
                RestConstant.RESTFUL_METHOD_POST, INCIDENT_DIAGNOSIS_STATUS, restfulParametes, getDefaultRestOptions());

            if (response == null || response.getStatus() != RestConstant.STATUS_OK) {
                LOGGER.error("[getIncidentDiagnosisStatus] Failed to get AI incident diagnosis status csn={}", incidentCsn);
                throw new ServiceException("Failed to get AI incident diagnosis status, status: " +
                    (response != null ? response.getStatus() : "null"));
            }

            ResponseResult responseResult = JSON.parseObject(response.getResponseContent(), ResponseResult.class);
            if (responseResult.getResultCode() == null || responseResult.getResultCode() != 0) {
                LOGGER.error("[getIncidentDiagnosisStatus] get AI incident diagnosis result error, csn={}, msg={}",
                    incidentCsn, responseResult.getResultMessage());
                throw new ServiceException(
                    "get AI incident diagnosis result error: " + responseResult.getResultMessage());
            }

            String dataJson = JSON.toJSONString(responseResult.getData());
            AIIncidentDiagnosisStatusDto diagnosisStatusDto =
                JSON.parseObject(dataJson, AIIncidentDiagnosisStatusDto.class);
            LOGGER.info("[getIncidentDiagnosisStatus] success csn={}, analysisStatus={}, diagnoseStatus={}",
                incidentCsn, diagnosisStatusDto.getAnalysisStatus(), diagnosisStatusDto.getDiagnosisStatus());
            return diagnosisStatusDto;
        } catch (Exception e) {
            throw new ServiceException("Error during get incident diagnosis status", e);
        }
    }
