package com.huawei.i2000.dvaiagentservice.executor;

import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.cloudsop.sys.util.i18n.ResourceUtil;
import com.huawei.i2000.dvaiagentservice.cluster.Incident;
import com.huawei.i2000.dvaiagentservice.cluster.IncidentManage;
import com.huawei.i2000.dvaiagentservice.dao.IncidentDao;
import com.huawei.i2000.dvaiagentservice.diagnose.enums.DiagnosticStatusEnum;
import com.huawei.i2000.dvaiagentservice.diagnose.enums.DiagnosticTypeEnum;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.PropertySource;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.concurrent.DelayQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;

/**
 * 功能描述
 *
 * @author l00851454
 * @since 2025/10/25
 */
@Component
@PropertySource("classpath:service-configure.properties")
public class DelayedIncidentScheduler {

    private static final Logger LOGGER = LoggerFactory.getLogger(DelayedIncidentScheduler.class);

    @Value("${delay_queue_max_capacity:256}")
    private int maxQueueCapacity;

    private final DelayQueue<DelayedIncidentTask> delayQueue = new DelayQueue<>();

    private final ReentrantLock queueLock = new ReentrantLock();

    private final ThreadPoolExecutor diagnosisThreadPoolExecutor;

    private final IncidentDao incidentDao;

    private final IncidentManage incidentManage;

    private final ExecutorService schedulerExecutor;

    @Value("${delay_time}")
    private long delayTimeInSeconds;

    private long delayTimeInMillis;

    private volatile boolean running = true;

    public static final int CLEARED_STATUS = 1;

    public static final String NO_NEED_DIAGNOSIS = "fault.agent.no.need.diagnosis";

    @Autowired
    public DelayedIncidentScheduler(
        @Qualifier("faultDiagnosisThreadPoolExecutor") ThreadPoolExecutor diagnosisThreadPoolExecutor,
        IncidentDao incidentDao, IncidentManage incidentManage,
        @Qualifier("incidentSchedulerExecutor") ExecutorService schedulerExecutor) {
        this.diagnosisThreadPoolExecutor = diagnosisThreadPoolExecutor;
        this.incidentDao = incidentDao;
        this.incidentManage = incidentManage;
        this.schedulerExecutor = schedulerExecutor;
    }

    public void addIncidentWithDelay(Incident incident)
        throws ServiceException {
        queueLock.lock();
        try {
            if (delayQueue.size() >= maxQueueCapacity) {
                handleRejectedTask(incident);
                return;
            }

            DelayedIncidentTask task = new DelayedIncidentTask(incident, this.delayTimeInMillis);
            delayQueue.offer(task);
            LOGGER.debug("Added incident {} to delay queue (current size: {}). Will execute at: {}",
                incident.getCsn(), delayQueue.size(), task.getExecuteTime());

        } finally {
            queueLock.unlock();
        }
    }

    private void handleRejectedTask(Incident incident)
        throws ServiceException {
        LOGGER.warn("Delay queue is full (size >= {}). Discarding incident: {}",
            maxQueueCapacity, incident.getCsn());
        Incident latestIncident = incidentDao.getIncidentByCsn(incident.getCsn());
        latestIncident.setDiagnosticStatus(DiagnosticStatusEnum.RESOURCE_INSUFFICIENT_NOT_EXECUTED);
        try {
            incidentDao.addIncident(Collections.singletonList(latestIncident));
        } catch (ServiceException e) {
            LOGGER.error("handleRejectedTask addIncident exception {}", e.getMessage());
        }
    }

    @PostConstruct
    public void startScheduler() {
        this.delayTimeInMillis = delayTimeInSeconds * 1000L;
        this.schedulerExecutor.execute(this::scheduleLoop);
        LOGGER.info("DelayedIncidentScheduler started with delay {}ms and queue capacity {}",
            delayTimeInMillis, maxQueueCapacity);
    }

    private void scheduleLoop() {
        while (running && !Thread.currentThread().isInterrupted()) {
            try {
                DelayedIncidentTask task = delayQueue.take();
                Incident incident = task.getIncident();
                if (!checkRecoveryStatus(incident.getCsn())) {
                    submitDiagnosisTask(incident);
                }

            } catch (InterruptedException e) {
                LOGGER.error("Scheduler thread interrupted, stopping...");
                Thread.currentThread().interrupt();
                break;
            } catch (Exception e) {
                LOGGER.error("Unexpected error in DelayedIncidentScheduler: ", e);
            }
        }
        LOGGER.info("DelayedIncidentScheduler scheduleLoop stopped");
    }

    private boolean checkRecoveryStatus(long csn)
        throws ServiceException {
        Incident incident = incidentDao.getIncidentByCsn(csn);
        if (incident == null) {
            LOGGER.error("Incident with csn {} not found in database.", csn);
            return true;
        }
        if (DiagnosticTypeEnum.MANUAL.equals(incident.getDiagnosticType())) {
            LOGGER.info("csn:{} has triggered a manual diagnosis, skip.", csn);
            return true;
        }

        if (incident.getClearStatus() == CLEARED_STATUS) {
            incident.setDiagnoseStartTime(System.currentTimeMillis());
            incident.setRepairAdvice(ResourceUtil.getMessage(NO_NEED_DIAGNOSIS));
            incident.setDiagnosticStatus(DiagnosticStatusEnum.DIAGNOSIS_SUCCESS);
            incident.setDiagnoseEndTime(System.currentTimeMillis());
            incidentDao.addIncident(Collections.singletonList(incident));
            return true;
        }
        return false;
    }

    private void submitDiagnosisTask(Incident incident)
        throws ServiceException {
        Incident latestIncident = incidentDao.getIncidentByCsn(incident.getCsn());
        LOGGER.info("submitDiagnosisTask, csn {}", incident.getCsn());

        try {
            diagnosisThreadPoolExecutor.execute(() -> {
                latestIncident.setDiagnosticStatus(DiagnosticStatusEnum.DIAGNOSING);
                latestIncident.setDiagnosticType(DiagnosticTypeEnum.AUTO);
                try {
                    incidentDao.addIncident(Collections.singletonList(latestIncident));
                    incidentManage.faultDiagnosis(latestIncident);
                    LOGGER.info("submitDiagnosisTask, faultDiagnosis, csn {}", incident.getCsn());
                    incidentDao.updateDiagnoseEndTime(latestIncident.getCsn(), System.currentTimeMillis());
                } catch (Exception e) {
                    Incident latestIncidentEx = null;
                    try {
